_WIDE = [(0x1100, 0x115F), (0x2E80, 0x303E), (0x3041, 0x33FF), (0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xA000, 0xA4CF),
         (0xAC00, 0xD7A3), (0xF900, 0xFAFF), (0xFE30, 0xFE4F), (0xFF00, 0xFF60), (0xFFE0, 0xFFE6), (0x1F300, 0x1F64F),
         (0x1F900, 0x1F9FF), (0x20000, 0x2FFFD), (0x30000, 0x3FFFD)]


def _w(ch):
    c = ord(ch)
    if 0x300 <= c <= 0x36F:
        return 0
    for lo, hi in _WIDE:
        if lo <= c <= hi:
            return 2
    return 1


def display_width(text):
    return sum(_w(ch) for ch in text)


def clip(text, width):
    if width < 0:
        raise ValueError("negative width")
    used = 0
    for i, ch in enumerate(text):
        w = _w(ch)
        if used + w > width:
            return text[:i]
        used += w
    return text


def pad_to(text, width):
    return text + " " * max(0, width - display_width(text))


def _wrap_paragraph(par, width, out):
    words = [w for w in par.split(" ") if w]
    if not words:
        out.append("")
        return
    line = ""
    for word in words:
        ww = display_width(word)
        if ww > width:
            if line:
                out.append(line)
                line = ""
            rest = word
            while display_width(rest) > width:
                piece = clip(rest, width)
                out.append(piece)
                rest = rest[len(piece):]
            line = rest
        elif not line:
            line = word
        elif display_width(line) + 1 + ww <= width:
            line += " " + word
        else:
            out.append(line)
            line = word
    if line:
        out.append(line)


def wrap(text, width):
    if width < 2:
        raise ValueError("width too small")
    out = []
    for par in text.split("\n"):
        _wrap_paragraph(par, width, out)
    return out

