mod common;
use common::Json;
use std::panic::{catch_unwind, AssertUnwindSafe};

trait ToJ {
    fn j(&self) -> Json;
}
impl ToJ for i32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u8 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for i64 {
    fn j(&self) -> Json {
        Json::Int(*self)
    }
}
impl ToJ for bool {
    fn j(&self) -> Json {
        Json::Bool(*self)
    }
}
impl ToJ for String {
    fn j(&self) -> Json {
        Json::Str(self.clone())
    }
}
impl<T: ToJ> ToJ for Vec<T> {
    fn j(&self) -> Json {
        Json::Arr(self.iter().map(|x| x.j()).collect())
    }
}
impl<T: ToJ> ToJ for Option<T> {
    fn j(&self) -> Json {
        match self {
            Some(x) => x.j(),
            None => Json::Null,
        }
    }
}

fn call(f: &str, a: &[Json]) -> Option<Result<Json, ()>> {
    Some(match f {
        "display_width" => Ok(col_wrap::display_width(a[0].str_()).j()),
        "clip" => col_wrap::clip(a[0].str_(), a[1].int_()).map(|v| v.j()).map_err(|_| ()),
        "pad_to" => Ok(col_wrap::pad_to(a[0].str_(), a[1].int_()).j()),
        "wrap" => col_wrap::wrap(a[0].str_(), a[1].int_()).map(|v| v.j()).map_err(|_| ()),
        _ => return None,
    })
}

